CREATE PROCEDURE grouped_totals(src_name VARCHAR)
RETURNS TABLE (BUCKET VARCHAR, TOTAL NUMBER(32,0))
LANGUAGE SQL
AS
$$
DECLARE
  res RESULTSET;
BEGIN
  res := (
      SELECT grp, SUM(amount) AS total FROM IDENTIFIER(:src_name) GROUP BY grp);
  RETURN TABLE(res);
END;
$$

